// Observabilidad: arma el reporte de auditoría del razonamiento del agente.
const item = $input.first().json;
const pasos = Array.isArray(item.intermediateSteps) ? item.intermediateSteps : [];

const traza = pasos.length
  ? pasos.map((p, i) => {
      const accion = p.action || {};
      const herramienta = accion.tool || 'sin herramienta';
      const entrada = JSON.stringify(accion.toolInput || {});
      const obs = p.observation;
      const salida = typeof obs === 'string' ? obs : JSON.stringify(obs || {});
      return (i + 1) + '. Herramienta: ' + herramienta + '\n   Entrada: ' + entrada + '\n   Resultado: ' + salida;
    }).join('\n\n')
  : 'El agente respondió sin activar herramientas en esta ejecución (la ramificación probabilística no se abrió).';

const reporte = [
  'REPORTE DE OBSERVABILIDAD - CHECKPOINT 1',
  '=========================================',
  'Workflow: ' + $workflow.name,
  'Ejecución: ' + $execution.id,
  'Fecha: ' + new Date().toISOString(),
  'Iteraciones con herramienta: ' + pasos.length,
  '',
  '--- TRAZA DEL RAZONAMIENTO (Execution Log) ---',
  traza,
  '',
  '--- RESPUESTA FINAL AL CLIENTE ---',
  item.output || '(sin salida)'
].join('\n');

return [{
  json: {
    ejecucion_id: $execution.id,
    workflow: $workflow.name,
    fecha: new Date().toISOString(),
    iteraciones_con_herramienta: pasos.length,
    herramientas_usadas: pasos.map(p => (p.action || {}).tool).filter(Boolean),
    respuesta_final: item.output || '',
    reporte: reporte
  }
}];
